use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub accession_key: String,
    pub stable_units: i64,
    pub fragile_units: i64,
    pub packing_stations: i64,
    pub expedited: bool,
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub accession_key: String,
    pub artifact_total: i64,
    pub packing_units: i64,
    pub capacity_units: i64,
    pub overflow_units: i64,
    pub inspection_rounds: i64,
    pub priority_score: i64,
    pub accession_state: String,
}

pub fn score(stable_units: i64, fragile_units: i64, packing_stations: i64, expedited: bool) -> i64 {
    let artifact_total = stable_units + fragile_units;
    let packing_units = stable_units * 6
        + fragile_units * 11
        + if expedited { packing_stations * 4 } else { 0 };
    let capacity_units = packing_stations * 40;
    let overflow_units = (packing_units - capacity_units).max(0);
    let inspection_rounds = artifact_total.div_euclid(5);

    packing_units + overflow_units * 5 + inspection_rounds * 7
}

pub fn calculate(value: &RequestInput) -> ResponseOutput {
    let artifact_total = value.stable_units + value.fragile_units;
    let packing_units = value.stable_units * 6
        + value.fragile_units * 11
        + if value.expedited { value.packing_stations * 4 } else { 0 };
    let capacity_units = value.packing_stations * 40;
    let overflow_units = (packing_units - capacity_units).max(0);

    ResponseOutput {
        accession_key: value.accession_key.clone(),
        artifact_total,
        packing_units,
        capacity_units,
        overflow_units,
        inspection_rounds: artifact_total.div_euclid(5),
        priority_score: score(
            value.stable_units,
            value.fragile_units,
            value.packing_stations,
            value.expedited,
        ),
        accession_state: if overflow_units == 0 { "accepted" } else { "queued" }.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_browser_score(a0: i64, a1: i64, a2: i64, a3: i32) -> i64 {
    score(a0, a1, a2, a3 != 0)
}

